import{_ as a,a0 as i,w as l,s as p,ao as h,I as n,x as t,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Linux 中為非 SSH 用户配置 SFTP 環境 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中為非 SSH 用户配置 SFTP 環境 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中為非 SSH 用户配置 SFTP 環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中為非 SSH 用户配置 SFTP 環境 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140723 How to configure chroot SFTP in Linux","title":"在 Linux 中為非 SSH 用户配置 SFTP 環境","tag":"201408","desc":""},"relativePath":"201408/20140723 How to configure chroot SFTP in Linux.md","filePath":"[post].md"}'),d={name:"201408/20140723 How to configure chroot SFTP in Linux.md"};function c(u,o,f,g,m,x){const s=i("Link");return l(),p("div",null,[o[13]||(o[13]=h(`<h1 id="在-linux-中為非-ssh-用户配置-sftp-環境" tabindex="-1">在 Linux 中為非 SSH 用户配置 SFTP 環境 <a class="header-anchor" href="#在-linux-中為非-ssh-用户配置-sftp-環境" aria-label="Permalink to “在 Linux 中為非 SSH 用户配置 SFTP 環境”">​</a></h1><p>在<strong>某些環境</strong>中，系統管理員想要允許極少數用户在可以傳輸文件到Linux機器中，但是不允許使用 SSH。要實現這一目的，我們可以使用<strong>SFTP</strong>，併為其構建chroot環境。</p><h3 id="sftp-chroot背景" tabindex="-1">SFTP &amp; chroot背景： <a class="header-anchor" href="#sftp-chroot背景" aria-label="Permalink to “SFTP &amp; chroot背景：”">​</a></h3><p><strong>SFTP</strong>是指<strong>SSH文件傳輸協議（SSH File Transfer protocol）或安全文件傳輸協議（Secure File Transfer Protocol）</strong>，它提供了可信數據流下的文件訪問、文件傳輸以及文件管理功能。當我們為SFTP配置chroot環境後，只有被許可的用户可以訪問，並被限制到他們的<strong>家目錄</strong>中，換言之：被許可的用户將處於牢籠環境中，在此環境中它們甚至不能切換它們的目錄。</p><p>在本文中，我們將配置<strong>RHEL 6.X</strong> 和 <strong>CentOS 6.X中的SFTP Chroot環境</strong>。我們開啓一個用户帳號‘<strong>Jack</strong>’，該用户將被允許在Linux機器上傳輸文件，但沒有ssh訪問權限。</p><h3 id="步驟-1-創建組" tabindex="-1">步驟：1 創建組 <a class="header-anchor" href="#步驟-1-創建組" aria-label="Permalink to “步驟：1  創建組”">​</a></h3><pre><code>[root@localhost ~]# groupadd  sftp_users
</code></pre><h3 id="步驟-2-分配附屬組-sftp-users-給用户" tabindex="-1">步驟：2 分配附屬組(sftp_users)給用户 <a class="header-anchor" href="#步驟-2-分配附屬組-sftp-users-給用户" aria-label="Permalink to “步驟：2 分配附屬組(sftp_users)給用户”">​</a></h3><p>如果用户在系統上不存在，使用以下命令創建（ LCTT 譯註：這裏給用户指定了一個不能登錄的 shell，以防止通過 ssh 登錄）：</p><pre><code>[root@localhost ~]# useradd  -G sftp_users  -s /sbin/nologin  jack
[root@localhost ~]# passwd jack
</code></pre><p>對於<strong>已經存在的用户</strong>，使用以下usermod命令進行修改：</p><pre><code>[root@localhost ~]# usermod –G sftp_users  -s /sbin/nologin  jack
</code></pre><p><strong>注意</strong>：如果你想要修改用户的<strong>默認家目錄</strong>，那麼可以在useradd和usermod命令中使用‘<strong>-d</strong>’選項，並設置<strong>合適的權限</strong>。</p><h3 id="步驟-3-現在編輯配置文件-etc-ssh-sshd-config" tabindex="-1">步驟：3 現在編輯配置文件 “/etc/ssh/sshd_config” <a class="header-anchor" href="#步驟-3-現在編輯配置文件-etc-ssh-sshd-config" aria-label="Permalink to “步驟：3 現在編輯配置文件 “/etc/ssh/sshd_config””">​</a></h3><pre><code># vi /etc/ssh/sshd_config
#comment out the below line and add a line like below
#Subsystem sftp /usr/libexec/openssh/sftp-server
Subsystem sftp internal-sftp

# add Below lines  at the end of file
  Match Group sftp_users
  X11Forwarding no
  AllowTcpForwarding no
  ChrootDirectory %h                      
  ForceCommand internal-sftp
</code></pre><h4 id="此處" tabindex="-1">此處： <a class="header-anchor" href="#此處" aria-label="Permalink to “此處：”">​</a></h4><ul><li><strong>Match Group sftp_users</strong> – 該參數指定以下的行將僅僅匹配sftp_users組中的用户</li><li><strong>ChrootDirectory %h</strong> – 該參數指定用户驗證後用於chroot環境的路徑（默認的用户家目錄）。對於用户 Jack，該路徑就是/home/jack。</li><li><strong>ForceCommand internal-sftp</strong> – 該參數強制執行內部sftp，並忽略任何~/.ssh/rc文件中的命令。</li></ul><p>重啓ssh服務</p><pre><code># service sshd restart
</code></pre><h3 id="步驟-4-設置權限" tabindex="-1">步驟：4 設置權限： <a class="header-anchor" href="#步驟-4-設置權限" aria-label="Permalink to “步驟：4 設置權限：”">​</a></h3><pre><code>[root@localhost ~]# chmod 755 /home/jack
[root@localhost ~]# chown root /home/jack
[root@localhost ~]# chgrp -R sftp_users /home/jack
</code></pre><p>如果你想要允許jack用户上傳文件，那麼創建一個上傳文件夾，設置權限如下：</p><pre><code>[root@localhost jack]# mkdir /home/jack/upload
[root@localhost jack]# chown jack. /home/jack upload/
</code></pre><h3 id="步驟-5-現在嘗試訪問系統並進行測試" tabindex="-1">步驟：5 現在嘗試訪問系統並進行測試 <a class="header-anchor" href="#步驟-5-現在嘗試訪問系統並進行測試" aria-label="Permalink to “步驟：5  現在嘗試訪問系統並進行測試”">​</a></h3><p>嘗試通過ssh訪問系統</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/07/ssh-try.png" alt=""></p><p>正如下圖所示，用户jack通過SFTP登錄，而且因為chroot環境不能切換目錄。</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/07/sftp-login.png" alt=""></p><p>現在進行<strong>上傳和下載</strong>測試，如下圖：</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/07/sftp-upload-download.png" alt=""></p><p>正如上圖所示，jack用户的上傳下載功能都工作得很好。</p><hr>`,32)),n("p",null,[o[1]||(o[1]=t("via: ",-1)),r(s,{href:"http://www.linuxtechi.com/configure-chroot-sftp-in-linux/"},{default:e(()=>[...o[0]||(o[0]=[t("http://www.linuxtechi.com/configure-chroot-sftp-in-linux/",-1)])]),_:1})]),n("p",null,[o[3]||(o[3]=t("原文作者：",-1)),r(s,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...o[2]||(o[2]=[t("Pradeep Kumar",-1)])]),_:1})]),n("p",null,[o[6]||(o[6]=t("譯者：",-1)),r(s,{href:"https://github.com/GOLinux"},{default:e(()=>[...o[4]||(o[4]=[t("GOLinux",-1)])]),_:1}),o[7]||(o[7]=t(" 校對：",-1)),r(s,{href:"https://github.com/wxy"},{default:e(()=>[...o[5]||(o[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[o[10]||(o[10]=t("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...o[8]||(o[8]=[t("LCTT",-1)])]),_:1}),o[11]||(o[11]=t(" 原創翻譯，",-1)),r(s,{href:"http://linux.cn/"},{default:e(()=>[...o[9]||(o[9]=[t("Linux中國",-1)])]),_:1}),o[12]||(o[12]=t(" 榮譽推出",-1))])])}const P=a(d,[["render",c]]);export{w as __pageData,P as default};
